'use strict';
const S=EduSchool;
const defaultsSchool={role:null,teacherName:'Учитель',studentKey:'',group:'',roster:[],grades:[],lessons:[],homework:[],remarks:[],done:[],hourPlans:[],preferences:{theme:'light',accent:'forest',avatar:'🦉',photo:'',motion:true}};
state.school={...defaultsSchool,...state.school,preferences:{...defaultsSchool.preferences,...state.school?.preferences}};
for(const key of ['roster','grades','lessons','homework','remarks','done','hourPlans'])if(!Array.isArray(state.school[key]))state.school[key]=[];
if(!['teacher','student'].includes(state.school.role))state.school.role=null;
const schoolPages={teacherhome:teacherHome,studenthome:studentHome,journal:journalPage,people:peoplePage,schedule:schedulePage,homework:homeworkPage,remarks:remarksPage,ranking:rankingPage,hours:hoursPage,settings:preferencesPage};
Object.assign(pages,{teacherhome:['Кабинет учителя','Ваш день, под контролем','Учебная работа, результаты и планы — в одном пространстве.','⌂'],studenthome:['Мой кабинет','Маленькие шаги. Большой прогресс','Следите за результатами и планируйте свой учебный день.','⌂'],journal:['Журнал оценок','Каждое достижение имеет значение','Оценки и динамика по выбранному предмету.','▤'],people:['Класс / группа','Знакомьтесь: ваша группа','Список обучающихся объединяет оценки, задания и рейтинг.','♧'],schedule:['Расписание','У каждого дела своё время','Недельное расписание выбранного класса или группы.','▦'],homework:['Домашние задания','Практика превращается в знание','Задания по всем предметам выбранной группы.','✓'],remarks:['Обратная связь','Слова, которые помогают расти','Замечания и похвала от учителя.','◌'],ranking:['Рейтинг группы','Растите вместе','Рейтинг по предметам и общий результат внутри группы.','↗'],hours:['Распределение часов','Время на важное','План учителя по темам выбранного предмета и группы.','◷'],settings:['Настройки','Сделайте EduLens своим','Профиль, тема, аватар и плавность интерфейса.','⚙']});
const teacherOrder=['teacherhome','journal','people','schedule','homework','remarks','ranking','hours','overview','topics','books','data','settings'];
const studentOrder=['studenthome','journal','schedule','homework','remarks','ranking','topics','settings'];
let peopleCache=null,peopleCacheContext='',recordEdit=null,rankingSubject='all',hoursDraft=null,hoursDraftKey='',lastAnimatedPage='';
function isTeacher(){return state.school.role==='teacher';}function isStudent(){return state.school.role==='student';}function roleHome(){return isStudent()?'studenthome':'teacherhome';}
function canVisit(k){return (isTeacher()?teacherOrder:isStudent()?studentOrder:['teacherhome','settings']).includes(k)||isTeacher()&&k==='plan';}
function guardTeacher(){if(isTeacher())return true;toast('Это действие доступно в кабинете учителя');return false;}
function uid(){return crypto.randomUUID?crypto.randomUUID():'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);}
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Qyzylorda',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function displayDate(d){return S.validDate(d)?new Date(d+'T12:00:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'short'}):'—';}
function basicContext(r){return r.type===state.profile.type&&Number(r.level)===Number(state.profile.level);}
function clearSchoolCache(){peopleCache=null;}
function allPeople(){const context=state.profile.type+'|'+state.profile.level;if(peopleCache&&peopleCacheContext===context)return peopleCache;const map=new Map();state.rows.forEach(r=>{if(r.institution_type===state.profile.type&&Number(r.level)===state.profile.level){const key=S.personKey(state.profile,r.class,r.student_id);map.set(key,{key,student_id:r.student_id,name:r.student_id,group:r.class,type:state.profile.type,level:state.profile.level,derived:true,demo:r.demo===true});}});state.school.roster.filter(basicContext).forEach(p=>map.set(p.key,p));peopleCache=[...map.values()];peopleCacheContext=context;return peopleCache;}
function groups(){return [...new Set([...allPeople().map(p=>p.group),...state.school.lessons.filter(basicContext).map(l=>l.group),...state.school.homework.filter(basicContext).map(h=>h.group)])].sort((a,b)=>a.localeCompare(b,'ru'));}
function activeGroup(){const gs=groups();return state.class!=='all'&&gs.includes(state.class)?state.class:gs.includes(state.school.group)?state.school.group:gs[0]||(state.profile.type==='school'?state.profile.level+'А':'Группа 1');}
function roster(){return allPeople().filter(p=>p.group===activeGroup());}
function currentStudent(){const p=allPeople().find(p=>p.key===state.school.studentKey);return p&&p.group===activeGroup()?p:null;}
function scoped(list){return state.school[list].filter(x=>basicContext(x)&&x.group===activeGroup());}
function visibleRecords(list){let rs=scoped(list);if(isStudent()&&(list==='grades'||list==='remarks'))rs=rs.filter(x=>x.studentKey===currentStudent()?.key);return rs;}
function knownSubjects(){return [...new Set([...W.subjects,state.profile.subject,...state.school.grades.filter(basicContext).map(g=>g.subject),...state.school.lessons.filter(basicContext).map(g=>g.subject)])];}
function avatarMarkup(cls=''){const p=state.school.preferences;return'<span class="avatar '+cls+'">'+(p.photo?'<img src="'+esc(p.photo)+'" alt="Аватар">':esc(p.avatar))+'</span>';}
function schoolFilters(){const onSchool=Object.hasOwn(schoolPages,page);if(onSchool){const gs=groups();const chosen=activeGroup();$('#class-filter').innerHTML=optionList((gs.length?gs:[chosen]).map(g=>[g,g]),chosen);state.school.group=chosen;$('#class-filter').value=chosen;$('#class-filter').onchange=e=>{state.school.group=e.target.value;state.class=e.target.value;hoursDraft=null;persist();render();};}else $('#class-filter').onchange=e=>{state.class=e.target.value;render();};$('#subject-filter').innerHTML=optionList(knownSubjects().map(s=>[s,s]),state.profile.subject);}
function decorateShell(){const order=isTeacher()?teacherOrder:studentOrder;const links=[...$('#nav').querySelectorAll('a')];links.sort((a,b)=>order.indexOf(a.hash.slice(1))-order.indexOf(b.hash.slice(1)));links.forEach(a=>$('#nav').append(a));const who=isStudent()?(currentStudent()?.name||'Ученик'):state.school.teacherName;$('#profile-settings').innerHTML=avatarMarkup()+'<div>'+esc(who)+'<small>'+(isTeacher()?'Кабинет учителя':isStudent()?'Кабинет ученика':'Выберите роль')+'</small></div><span>⚙</span>';$('.header-right').innerHTML='<span class="private-dot"></span><span>Данные этого браузера</span><button class="role-chip" id="switch-role">'+(isTeacher()?'Учитель':isStudent()?'Ученик':'Выбрать роль')+' ⇄</button><button class="avatar-button" id="header-settings" aria-label="Настройки профиля">'+avatarMarkup('mini')+'</button>';$('#switch-role').onclick=()=>openRole(true);$('#header-settings').onclick=()=>navigate('settings');$('#profile-settings').onclick=()=>navigate('settings');$('#import-top').hidden=!isTeacher();$('#source-data').textContent=isTeacher()?'Данные ↗':'Профиль ↗';$('.nav-label').textContent=isTeacher()?'ПРОСТРАНСТВО УЧИТЕЛЯ':'МОЁ ОБУЧЕНИЕ';if(Object.hasOwn(schoolPages,page)){$('#export').hidden=true;$('#book-filter').closest('label').hidden=true;$('#source-banner').innerHTML='<div class="source-banner"><span>◉</span><span>'+esc(W.caption(state.profile))+' · '+esc(activeGroup())+' · '+(roster().some(p=>p.demo)?'есть демоданные · ':'')+'локальное пространство</span><button id="cabinet-help">Как это работает ↗</button></div>';$('#cabinet-help').onclick=startTutorial;}else{$('#export').hidden=false;$('#book-filter').closest('label').hidden=false;}
if(lastAnimatedPage!==page){$('#content').classList.remove('page-enter');void $('#content').offsetWidth;$('#content').classList.add('page-enter');lastAnimatedPage=page;}applyPreferences();}
function applyPreferences(){const p=state.school.preferences;document.documentElement.dataset.theme=p.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):p.theme;document.documentElement.dataset.accent=p.accent;document.documentElement.dataset.motion=p.motion?'on':'off';}
function hero(title,description,icon='✦'){return'<div class="cabinet-hero"><div><div class="eyebrow">'+(isTeacher()?'ПРОСТРАНСТВО УЧИТЕЛЯ':'МОЁ ОБУЧЕНИЕ')+'</div><h2>'+esc(title)+'</h2><p>'+esc(description)+'</p><span class="hero-pill">'+esc(activeGroup())+' · '+roster().length+' обучающихся</span></div><div class="hero-orbit"><span>'+icon+'</span></div></div>';}
function smallStats(items){return'<div class="stats cabinet-stats">'+items.map(([value,label,icon,sub])=>'<article class="stat"><div class="stat-top">'+label+'<span class="stat-icon">'+icon+'</span></div><div class="stat-number"><strong>'+value+'</strong></div><div class="stat-foot">'+sub+'</div></article>').join('')+'</div>';}
function actionButton(label,kind){return'<button class="button primary" data-new="'+kind+'">＋ '+label+'</button>';}
function emptySchool(text,action=''){return'<div class="empty school-empty"><span>✧</span><p>'+text+'</p>'+action+'</div>';}
function teacherHome(){if(!isTeacher())return hero('Добро пожаловать в EduLens','Выберите роль, чтобы открыть своё пространство.');const gs=visibleRecords('grades'),hw=scoped('homework'),ls=scoped('lessons');return hero('Здравствуйте, '+state.school.teacherName+'!','Помогайте каждому двигаться вперёд. Всё остальное мы собрали здесь.','✦')+smallStats([[roster().length,'В вашей группе','♧','Список в разделе «Класс / группа»'],[gs.length,'Записей в журнале','▤','Оценки по всем предметам'],[ls.length,'Занятий в неделю','◷','Расписание группы'],[hw.filter(h=>h.due>=today()).length,'Актуальных заданий','✓','Срок сегодня или позже']])+'<div class="quick-actions"><button data-new="grade">▤ <b>Поставить оценку</b><span>Зафиксировать результат ↗</span></button><button data-new="homework">✓ <b>Задать на дом</b><span>Добавить практику ↗</span></button><button data-new="lesson">◷ <b>Добавить занятие</b><span>Запланировать неделю ↗</span></button></div><div class="grid-main">'+panel('Ритм вашей недели','Ближайшие дни в недельном расписании',lessonList(ls.slice().sort((a,b)=>a.day-b.day||a.start.localeCompare(b.start)).slice(0,4)),'<button class="text-link" data-page="schedule">Всё расписание ↗</button>')+panel('Сильные стороны группы','По оценкам журнала',rankingMini(),'<button class="text-link" data-page="ranking">Рейтинг ↗</button>')+'</div><div class="bottom-grid">'+panel('Планирование с опорой на данные','Часы по темам и предметам','<div class="panel-body"><div class="plan-preview"><span>◷</span><div><strong>Учебное время — под вашим контролем</strong><p>Составьте план вручную или используйте результаты тестирования.</p></div></div><button class="button wide" data-page="hours">Открыть распределение часов →</button></div>')+panel('Начните со своей группы','Добавляйте обучающихся или исследуйте пример','<div class="panel-body"><p class="small-note">В демопримере — 20 вымышленных обучающихся, оценки по трём предметам, занятия и задания.</p><button class="button" id="load-school-demo">Открыть пример на 20 человек</button><button class="text-link wide" data-page="people">Управлять списком группы →</button></div>')+'</div>';}
function studentHome(){const p=currentStudent(),grades=visibleRecords('grades'),homework=scoped('homework'),remaining=homework.filter(h=>!isDone(h.id)),rank=S.rank(roster(),scoped('grades')).find(x=>x.key===p?.key);return hero(p?'Привет, '+p.name+'!':'Это ваш учебный кабинет',p?'Каждый день — ещё один шаг к цели. Посмотрим, что получилось.':'Выберите себя в списке группы, чтобы увидеть личные результаты.','✧')+(!p?'<div class="callout"><button class="button primary" id="choose-identity">Выбрать себя из списка</button> <span>Учитель сначала добавляет обучающихся в группу.</span></div>':'')+smallStats([[grades.length,'Моих оценок','▤','По всем предметам'],[pct(S.mean(grades.map(S.normalized))),'Средний результат','↗','Нормированные оценки журнала'],[rank?.rank||'—','Место в группе','♧','Общий рейтинг по предметам'],[remaining.length,'Заданий впереди','✓','Ещё не отмечены выполненными']])+'<div class="grid-main">'+panel('Что нужно сделать','Домашние задания группы',homeworkCards(remaining.slice(0,3)),'<button class="text-link" data-page="homework">Все задания ↗</button>')+panel('Мои последние результаты','Оценки, которые поставил учитель',gradeList(grades.slice().reverse().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5)),'<button class="text-link" data-page="journal">Журнал ↗</button>')+'</div>'+panel('Расписание недели','Занятия выбранной группы',lessonList(scoped('lessons').sort((a,b)=>a.day-b.day||a.start.localeCompare(b.start)).slice(0,5)),'<button class="text-link" data-page="schedule">Открыть неделю ↗</button>');}
function rankingMini(){const ranked=S.rank(roster(),scoped('grades')).filter(p=>p.rank!==null).slice(0,3);return'<div class="panel-body">'+(ranked.length?ranked.map((p,i)=>'<div class="rank-mini"><span class="rank-medal m'+i+'">'+p.rank+'</span><span><b>'+esc(p.name)+'</b><small>'+esc(p.student_id)+'</small></span><strong>'+(p.score===null?'—':fmt(p.score,2)+'%')+'</strong></div>').join(''):emptySchool('Добавьте оценки — и здесь появится рейтинг.'))+'</div>';}
function journalPage(){const list=visibleRecords('grades').filter(g=>g.subject===state.profile.subject).sort((a,b)=>b.date.localeCompare(a.date));return'<div class="section-bar"><span class="section-note">'+esc(activeGroup())+' · '+esc(state.profile.subject)+'</span>'+(isTeacher()?actionButton('Поставить оценку','grade'):'<span class="badge green">Только мои оценки</span>')+'</div>'+panel('Журнал результатов','Любая шкала приводится к процентам для сравнения',list.length?'<div class="table-wrap"><table><thead><tr><th>Обучающийся</th><th>Работа</th><th>Дата</th><th>Оценка</th><th>Результат</th><th>Комментарий</th>'+(isTeacher()?'<th>Действия</th>':'')+'</tr></thead><tbody>'+list.map(g=>'<tr><td>'+esc(personName(g.studentKey))+'</td><td>'+esc(g.title)+'</td><td>'+displayDate(g.date)+'</td><td><span class="grade-pill">'+g.score+' / '+g.max+'</span></td><td>'+pct(S.normalized(g))+'</td><td class="wrap-cell">'+esc(g.comment||'—')+'</td>'+(isTeacher()?'<td>'+editButtons('grade',g.id)+'</td>':'')+'</tr>').join('')+'</tbody></table></div>':emptySchool(isTeacher()?'По этому предмету пока нет оценок. Добавьте первую запись.':'По этому предмету учитель пока не добавил вам оценок.'))+'<div class="callout section-gap">Оценки журнала и результаты диагностических тестов хранятся отдельно. Анализ тем и рекомендации по часам используют диагностические данные из раздела «Данные».</div>';}
function gradeList(list){return'<div class="panel-body">'+(list.length?list.map(g=>'<div class="activity-row"><span class="grade-pill">'+g.score+'/'+g.max+'</span><div><strong>'+esc(g.title)+'</strong><small>'+esc(g.subject)+' · '+displayDate(g.date)+'</small></div></div>').join(''):emptySchool('Новых оценок пока нет.'))+'</div>';}
function personName(key){return allPeople().find(p=>p.key===key)?.name||'Обучающийся';}
function editButtons(kind,id){return'<div class="row-actions"><button class="text-link" data-edit="'+kind+'" data-id="'+esc(id)+'">Изменить</button><button class="text-link danger" data-delete="'+kind+'" data-id="'+esc(id)+'">Удалить</button></div>';}
function peoplePage(){return'<div class="section-bar"><span class="section-note">'+esc(activeGroup())+' · '+roster().length+' человек</span>'+actionButton('Добавить обучающегося','person')+'</div>'+panel('Список группы','ID объединяет результаты по разным предметам','<div class="panel-body"><p class="small-note">Можно использовать псевдонимы вместо полных имён. Список из диагностических данных подключается автоматически.</p></div>'+(roster().length?'<div class="table-wrap"><table><thead><tr><th>ID</th><th>Имя / псевдоним</th><th>Группа</th><th>Оценок</th><th>Действия</th></tr></thead><tbody>'+roster().map(p=>'<tr><td>'+esc(p.student_id)+'</td><td>'+esc(p.name)+'</td><td>'+esc(p.group)+'</td><td>'+scoped('grades').filter(g=>g.studentKey===p.key).length+'</td><td><button class="text-link" data-edit="person" data-id="'+esc(p.key)+'">Изменить имя</button></td></tr>').join('')+'</tbody></table></div>':emptySchool('В этой группе ещё нет обучающихся.')))+'<div class="section-gap">'+panel('Нужен пример?','20 вымышленных обучающихся, три предмета','<div class="panel-body"><button class="button" id="load-school-demo">Открыть пример на 20 человек</button><p class="small-note">Пример добавляется в отдельную демогруппу и сохраняет ваши данные.</p></div>')+'</div>';}
const dayNames=['','Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'];
function schedulePage(){const ls=scoped('lessons');return'<div class="section-bar"><span class="section-note">Все предметы · '+esc(activeGroup())+'</span>'+(isTeacher()?actionButton('Добавить занятие','lesson'):'<span class="badge green">Расписание учителя</span>')+'</div><div class="week-grid">'+[1,2,3,4,5,6,7].map(day=>'<section class="day-card"><div class="day-heading"><span>'+dayNames[day]+'</span><b>'+ls.filter(l=>l.day===day).length+'</b></div>'+ls.filter(l=>l.day===day).sort((a,b)=>a.start.localeCompare(b.start)).map(l=>'<article class="lesson-card"><span class="lesson-time">'+l.start+' — '+l.end+'</span><h3>'+esc(l.subject)+'</h3><p>'+esc(l.room||'Аудитория не указана')+'</p>'+(isTeacher()?editButtons('lesson',l.id):'')+'</article>').join('')+(!ls.some(l=>l.day===day)?'<div class="day-free">Свободный день <span>☀</span></div>':'')+'</section>').join('')+'</div>';
}
function lessonList(ls){return'<div class="panel-body">'+(ls.length?ls.map(l=>'<div class="activity-row"><span class="time-tile">'+l.start+'<small>'+dayNames[l.day].slice(0,2)+'</small></span><div><strong>'+esc(l.subject)+'</strong><small>'+esc(l.room||'Аудитория не указана')+' · до '+l.end+'</small></div></div>').join(''):emptySchool('Занятия пока не добавлены.'))+'</div>';}
function isDone(id){return state.school.done.some(d=>d.homeworkId===id&&d.studentKey===currentStudent()?.key);}
function homeworkPage(){return'<div class="section-bar"><span class="section-note">Все предметы · '+esc(activeGroup())+'</span>'+(isTeacher()?actionButton('Задать на дом','homework'):'<span class="badge green">Отмечайте выполненные задания</span>')+'</div>'+homeworkCards(scoped('homework').slice().sort((a,b)=>a.due.localeCompare(b.due)));}
function homeworkCards(list){return'<div class="homework-list">'+(list.length?list.map(h=>{const done=isDone(h.id),late=h.due<today()&&!done;return'<article class="homework-card '+(done?'done':'')+'"><div class="section-bar"><span class="badge '+(done?'green':late?'red':'')+'">'+esc(h.subject)+'</span><span class="due-date">'+(late?'Срок прошёл · ':'До ')+displayDate(h.due)+'</span></div><h3>'+esc(h.title)+'</h3><p>'+esc(h.description)+'</p><div class="homework-bottom">'+(isTeacher()?editButtons('homework',h.id):'<button class="button '+(done?'':'primary')+'" data-done="'+esc(h.id)+'" '+(!currentStudent()?'disabled':'')+'>'+(done?'✓ Выполнено · отменить':'Отметить выполненным')+'</button>')+'<span class="small-note">'+(isTeacher()?'Выполнено в этом браузере: '+state.school.done.filter(d=>d.homeworkId===h.id).length:done?'Хорошая работа!':'Практика — ваш следующий шаг')+'</span></div></article>';}).join(''):emptySchool('Домашних заданий пока нет.'))+'</div>';}
function remarksPage(){const rs=visibleRecords('remarks').sort((a,b)=>b.date.localeCompare(a.date));return'<div class="section-bar"><span class="section-note">Обратная связь · '+esc(activeGroup())+'</span>'+(isTeacher()?actionButton('Оставить сообщение','remark'):'<span class="badge green">Только мои сообщения</span>')+'</div><div class="feedback-grid">'+(rs.length?rs.map(r=>'<article class="feedback-card '+(r.kind==='praise'?'praise':'')+'"><div class="section-bar"><span class="badge '+(r.kind==='praise'?'green':'')+'">'+(r.kind==='praise'?'✦ Похвала':'◌ Замечание')+'</span><span class="due-date">'+displayDate(r.date)+'</span></div><h3>'+esc(personName(r.studentKey))+'</h3><small>'+esc(r.subject)+'</small><p>'+esc(r.text)+'</p>'+(isTeacher()?editButtons('remark',r.id):'')+'</article>').join(''):emptySchool('Здесь появится обратная связь от учителя.'))+'</div>';}
function rankingPage(){const subjects=[...new Set(scoped('grades').map(g=>g.subject))];if(rankingSubject!=='all'&&!subjects.includes(rankingSubject))rankingSubject='all';const ranked=S.rank(roster(),scoped('grades'),rankingSubject),rated=ranked.filter(p=>p.rank!==null),my=currentStudent()?.key;return'<div class="ranking-intro"><div><span class="eyebrow">ВМЕСТЕ К НОВЫМ РЕЗУЛЬТАТАМ</span><h2>У каждого свой путь. У группы — общий рост.</h2><p>'+esc(activeGroup())+' · '+roster().length+' обучающихся · с оценками: '+rated.length+'</p></div><span class="ranking-star">✦</span></div><div class="subject-tabs"><button data-rank-subject="all" class="'+(rankingSubject==='all'?'selected':'')+'">Все предметы</button>'+subjects.map(s=>'<button data-rank-subject="'+esc(s)+'" class="'+(rankingSubject===s?'selected':'')+'">'+esc(s)+'</button>').join('')+'</div>'+panel('Рейтинг группы',rankingSubject==='all'?'Общий результат: среднее результатов по предметам':esc(rankingSubject),'<div class="table-wrap"><table><thead><tr><th>Место</th><th>Обучающийся</th>'+subjects.map(s=>'<th>'+esc(s)+'</th>').join('')+'<th>Результат</th><th>Оценок</th></tr></thead><tbody>'+ranked.map(p=>'<tr class="'+(my===p.key&&isStudent()?'my-row':'')+'"><td><span class="rank-number '+(p.rank&&p.rank<=3?'top-rank':'')+'">'+(p.rank||'—')+'</span></td><td>'+esc(isStudent()&&p.key!==my?p.student_id:p.name)+(p.key===my&&isStudent()?'<span class="badge green">Вы</span>':'')+'</td>'+subjects.map(s=>'<td>'+(p.subjects[s]==null?'—':fmt(p.subjects[s],2)+'%')+'</td>').join('')+'<td><b>'+(p.score===null?'—':fmt(p.score,2)+'%')+'</b></td><td>'+p.count+'</td></tr>').join('')+'</tbody></table></div>')+'<div class="callout section-gap">Рейтинг строится по оценкам журнала внутри группы. Баллы приводятся к процентам. В общем рейтинге предметы имеют равный вес; число оценок и охват предметов могут различаться. При равном результате место одинаковое. Без оценок место не присваивается.</div>';}
function planKey(){return JSON.stringify([state.profile.type,state.profile.level,activeGroup(),state.profile.subject]);}
function getHoursDraft(){const key=planKey();if(!hoursDraft||hoursDraftKey!==key){const saved=state.school.hourPlans.find(p=>p.key===key);const ts=E.aggregate(contextRows().filter(r=>r.class===activeGroup()));hoursDraft=saved?JSON.parse(JSON.stringify(saved)):{key,budget:ts.reduce((n,t)=>n+t.hours,0)||12,rows:ts.length?ts.map(t=>({name:t.name,hours:t.hours,locked:false})):[{name:'Введение',hours:2,locked:false},{name:'Основные темы',hours:8,locked:false},{name:'Практика и проверка',hours:2,locked:false}]};hoursDraftKey=key;}return hoursDraft;}
function hoursPage(){const draft=getHoursDraft(),sum=draft.rows.reduce((n,r)=>n+Number(r.hours||0),0),saved=state.school.hourPlans.find(p=>p.key===draft.key);return'<div class="callout">План для '+esc(activeGroup())+' по предмету «'+esc(state.profile.subject)+'». Распределите доступные часы между темами. Для предложения на основе результатов нужны диагностические тесты по этой группе.</div><section class="panel"><div class="panel-head"><div><h2>План учителя по темам</h2><div class="panel-sub">Ручное распределение с проверкой общего объёма</div></div><span class="badge '+(sum===draft.budget?'green':'red')+'">'+sum+' / '+draft.budget+' ч</span></div><div class="panel-body"><div class="hours-budget"><label>Общий объём, ч <input type="number" id="teacher-budget" min="1" max="10000" value="'+draft.budget+'"></label><span class="small-note">При сохранении сумма часов должна совпасть с объёмом.</span></div><div class="table-wrap"><table class="hours-table"><thead><tr><th>Тема</th><th>Часы</th><th>Закрепить часы</th><th></th></tr></thead><tbody>'+draft.rows.map((r,i)=>'<tr data-hour-row="'+i+'"><td><input aria-label="Тема плана '+(i+1)+'" data-hour="name" maxlength="160" value="'+esc(r.name)+'"></td><td><input aria-label="Часы плана '+(i+1)+'" type="number" min="1" max="1000" data-hour="hours" value="'+r.hours+'"></td><td><input aria-label="Закрепить часы '+(i+1)+'" type="checkbox" data-hour="locked" '+(r.locked?'checked':'')+'></td><td><button class="delete-row" data-remove-hour="'+i+'" aria-label="Удалить тему '+(i+1)+'">×</button></td></tr>').join('')+'</tbody></table></div><div class="editor-actions"><button class="button" id="add-hour-topic">＋ Добавить тему</button><button class="button" id="suggest-teacher-hours">✧ Предложить по результатам</button></div><div id="hours-feedback" role="status"></div><button class="button primary" id="save-teacher-hours">Сохранить план</button> <button class="button" id="download-teacher-hours">↓ Скачать CSV</button>'+(saved?'<p class="small-note">Последнее сохранение: '+esc(saved.updatedAt)+'. Текущие изменения применятся после сохранения.</p>':'')+'<p class="small-note">Закреплённые темы сохраняют часы при автоматическом предложении. Увеличение часов — предложение для проверки учителем, без обещания роста баллов.</p></div></section><div class="section-gap"><button class="text-link" data-page="plan">Открыть подробное аналитическое обоснование →</button></div>';}
function readHours(){const d=getHoursDraft();d.budget=Number($('#teacher-budget').value);d.rows=[...document.querySelectorAll('[data-hour-row]')].map(tr=>({name:tr.querySelector('[data-hour=name]').value.trim(),hours:Number(tr.querySelector('[data-hour=hours]').value),locked:tr.querySelector('[data-hour=locked]').checked}));return d;}
function preferencesPage(){const p=state.school.preferences;return'<div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2>Ваш профиль</h2><div class="panel-sub">Небольшие детали, которые делают пространство вашим</div></div></div><div class="panel-body"><div class="profile-preview">'+avatarMarkup('large-avatar')+'<div><h3>'+esc(isTeacher()?state.school.teacherName:currentStudent()?.name||'Ученик')+'</h3><span class="badge green">'+(isTeacher()?'Учитель':'Ученик / студент')+'</span></div></div>'+(isTeacher()?'<label class="stack-label">Как к вам обращаться<input id="display-name" maxlength="60" value="'+esc(state.school.teacherName)+'"></label>':'<div class="callout">'+esc(currentStudent()?.name||'Личность в группе не выбрана')+'<br><button class="text-link" id="choose-identity">Выбрать себя в списке →</button></div>')+'<p class="settings-label">Аватар</p><div class="avatar-options">'+['🦉','🌱','📚','🚀','🐱','✦'].map(a=>'<button class="avatar-option '+(p.avatar===a&&!p.photo?'selected':'')+'" data-avatar="'+a+'" aria-label="Аватар '+a+'">'+a+'</button>').join('')+'</div><label class="avatar-upload">Добавить своё фото<input id="avatar-file" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="small-note">PNG, JPG или WebP до 500 КБ. Фото остаётся в этом браузере.</p>'+(p.photo?'<button class="text-link danger" id="remove-avatar">Убрать фото</button>':'')+'</div></section><section class="panel"><div class="panel-head"><div><h2>Оформление</h2><div class="panel-sub">Спокойная работа в вашем ритме</div></div></div><div class="panel-body"><p class="settings-label">Тема интерфейса</p><div class="theme-options">'+[['light','Светлая','☀'],['dark','Тёмная','☾'],['warm','Тёплая','◒'],['system','Системная','◈']].map(([key,label,icon])=>'<button class="theme-option '+(p.theme===key?'selected':'')+'" data-theme-choice="'+key+'"><span class="theme-preview '+key+'">'+icon+'</span>'+label+'</button>').join('')+'</div><p class="settings-label">Цвет акцента</p><div class="accent-options">'+[['forest','Зелёный'],['blue','Синий'],['purple','Сиреневый']].map(([key,label])=>'<button class="accent-option '+key+' '+(p.accent===key?'selected':'')+'" data-accent-choice="'+key+'" aria-label="'+label+'" title="'+label+'"></button>').join('')+'</div><label class="motion-toggle"><span><b>Плавные анимации</b><small>Появление карточек, диаграмм и переходы</small></span><input id="motion-toggle" type="checkbox" '+(p.motion?'checked':'')+'></label><p class="small-note">Настройка уменьшения движения в системе всегда учитывается.</p></div></section></div><div class="section-gap">'+panel('Пространство и роль','Управление текущим представлением','<div class="panel-body"><div class="settings-actions"><button class="button" id="settings-institution">Настроить учреждение и предмет</button><button class="button" id="settings-switch-role">Сменить роль</button><button class="button" id="settings-tutorial">Пройти туториал</button></div><p class="small-note">Локальный прототип: выбор роли переключает кабинет и доступные кнопки, но не заменяет проверку учётной записи. Совместная работа с других устройств и серверная проверка прав пока не подключены.</p></div>')+'</div>';}
function field(label,name,value='',type='text',extra=''){return'<label class="stack-label">'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>';}
function selectField(label,name,items,value){return'<label class="stack-label">'+label+'<select name="'+name+'">'+optionList(items,value)+'</select></label>';}
function textField(label,name,value='',max=2000){return'<label class="stack-label full-field">'+label+'<textarea name="'+name+'" maxlength="'+max+'" rows="4" required>'+esc(value)+'</textarea></label>';}
function personSelect(value){return selectField('Обучающийся','studentKey',[['','Выберите из списка'],...roster().map(p=>[p.key,p.name+' · '+p.student_id])],value);}
function openRecord(kind,id=null){if(!guardTeacher())return;const lists={grade:'grades',lesson:'lessons',homework:'homework',remark:'remarks'};const person=kind==='person'&&id?allPeople().find(p=>p.key===id):null;const r=id&&lists[kind]?state.school[lists[kind]].find(x=>x.id===id):{};if(id&&!r&&!person){toast('Запись не найдена');return;}recordEdit={kind,id};let fields='',title='';
if(kind==='person'){title=person?'Имя обучающегося':'Добавить в группу';fields=field('ID обучающегося','student_id',person?.student_id||'','text','required maxlength="80" '+(person?'readonly':''))+field('Имя или псевдоним','name',person?.name||'','text','required maxlength="80"')+field('Класс / группа','group',person?.group||activeGroup(),'text','required maxlength="80" '+(person?'readonly':''));}
if(kind==='grade'){title=id?'Изменить оценку':'Новая оценка';fields=personSelect(r?.studentKey)+selectField('Предмет','subject',knownSubjects().map(s=>[s,s]),r?.subject||state.profile.subject)+field('Работа / тема','title',r?.title||'','text','required maxlength="160"')+field('Дата','date',r?.date||today(),'date','required')+field('Полученный балл','score',r?.score??'','number','required min="0" max="1000" step="any"')+field('Максимальный балл','max',r?.max||5,'number','required min="1" max="1000" step="any"')+field('Комментарий','comment',r?.comment||'','text','maxlength="500"');}
if(kind==='lesson'){title=id?'Изменить занятие':'Запланировать занятие';fields=selectField('День недели','day',dayNames.slice(1).map((n,i)=>[i+1,n]),r?.day||1)+selectField('Предмет','subject',knownSubjects().map(s=>[s,s]),r?.subject||state.profile.subject)+field('Начало','start',r?.start||'09:00','time','required')+field('Окончание','end',r?.end||'09:45','time','required')+field('Аудитория / место','room',r?.room||'','text','maxlength="120"');}
if(kind==='homework'){title=id?'Изменить задание':'Новое домашнее задание';fields=selectField('Предмет','subject',knownSubjects().map(s=>[s,s]),r?.subject||state.profile.subject)+field('Срок выполнения','due',r?.due||today(),'date','required')+field('Название','title',r?.title||'','text','required maxlength="160"')+textField('Что нужно сделать','description',r?.description||'');}
if(kind==='remark'){title=id?'Изменить сообщение':'Обратная связь';fields=personSelect(r?.studentKey)+selectField('Тип сообщения','kind',[['note','Замечание'],['praise','Похвала']],r?.kind||'note')+selectField('Предмет','subject',knownSubjects().map(s=>[s,s]),r?.subject||state.profile.subject)+field('Дата','date',r?.date||today(),'date','required')+textField('Сообщение','text',r?.text||'',1000);}
if(!title)return;$('#record-dialog').innerHTML='<div class="modal-head"><span class="eyebrow">КАБИНЕТ УЧИТЕЛЯ · '+esc(activeGroup())+'</span><button class="icon-button" id="close-record" aria-label="Закрыть форму">×</button></div><h2>'+title+'</h2><form id="record-form" class="record-form">'+fields+'<div class="full-field form-feedback" role="alert" id="record-feedback"></div><div class="full-field modal-actions"><button class="button" type="button" id="cancel-record">Отмена</button><button class="button primary" type="submit">Сохранить</button></div></form>';$('#close-record').onclick=()=>$('#record-dialog').close();$('#cancel-record').onclick=()=>$('#record-dialog').close();$('#record-form').onsubmit=saveRecord;$('#record-dialog').showModal();}
function saveRecord(event){event.preventDefault();if(!guardTeacher())return;const data=Object.fromEntries(new FormData(event.target)),{kind,id}=recordEdit;let errors=[],list='';const scopeData={type:state.profile.type,level:state.profile.level,group:activeGroup()};let record={...scopeData,...data,id:id||uid()};
if(kind==='person'){const group=data.group.trim(),student_id=data.student_id.trim(),name=data.name.trim(),key=S.personKey(state.profile,group,student_id);if(!student_id||!name||!group)errors.push('Заполните ID, имя и группу');if(!id&&allPeople().some(p=>p.key===key))errors.push('Этот ID уже есть в группе');if(!errors.length){const p={...scopeData,key,student_id,name,group};state.school.roster=state.school.roster.filter(x=>x.key!==key);state.school.roster.push(p);state.school.group=group;state.class=group;}}
if(kind==='grade'){list='grades';record.score=Number(data.score);record.max=Number(data.max);errors=S.gradeErrors(record,roster());}
if(kind==='lesson'){list='lessons';record.day=Number(data.day);errors=S.lessonErrors(record,state.school.lessons.filter(l=>!l.demo||l.group===record.group));}
if(kind==='homework'){list='homework';if(!data.title.trim()||!data.description.trim())errors.push('Заполните название и описание');if(!S.validDate(data.due))errors.push('Укажите корректный срок');}
if(kind==='remark'){list='remarks';if(!roster().some(p=>p.key===data.studentKey))errors.push('Выберите обучающегося');if(!data.text.trim())errors.push('Напишите сообщение');if(!S.validDate(data.date))errors.push('Укажите дату');if(!['note','praise'].includes(data.kind))errors.push('Выберите тип сообщения');}
if(errors.length){$('#record-feedback').textContent=errors.join('. ');return;}if(list){state.school[list]=state.school[list].filter(x=>x.id!==record.id);state.school[list].push(record);}const ok=persist();$('#record-dialog').close();render();toast(ok?'Запись сохранена':'Запись доступна в этой вкладке');}
function removeRecord(kind,id){if(!guardTeacher())return;const list={grade:'grades',lesson:'lessons',homework:'homework',remark:'remarks'}[kind];if(!list)return;const found=state.school[list].find(r=>r.id===id);if(!found)return;const dialog=$('#record-dialog');dialog.innerHTML='<div class="modal-head"><span class="eyebrow">УДАЛЕНИЕ ЗАПИСИ</span><button class="icon-button" id="cancel-delete" aria-label="Отмена">×</button></div><h2>Удалить эту запись?</h2><p>'+esc(found.title||found.subject||'Сообщение')+'</p><div class="modal-actions"><button class="button" id="keep-record">Оставить</button><button class="button primary" id="confirm-delete">Удалить запись</button></div>';$('#cancel-delete').onclick=$('#keep-record').onclick=()=>dialog.close();$('#confirm-delete').onclick=()=>{if(!guardTeacher())return;state.school[list]=state.school[list].filter(x=>x.id!==id);persist();dialog.close();render();toast('Запись удалена');};dialog.showModal();}
function seedSchoolDemo(){if(!guardTeacher())return;const group=state.profile.type==='school'?'Демо · '+state.profile.level+'А (20)':'Демо · группа '+state.profile.level+' (20)',scopeData={type:state.profile.type,level:state.profile.level,group};const prefix='cab-demo-'+state.profile.type+'-'+state.profile.level+'-';if(state.school.roster.some(p=>p.demoTag===prefix)){state.school.group=group;state.class=group;render();toast('Открыта демогруппа. Новые записи не дублируются.');return;}
const names=['Азамат','Алина','Диас','Аружан','Мирас','Айша','Тимур','Дана','Ерасыл','Амина','Нурислам','София','Арман','Медина','Санжар','Аяулым','Данияр','Жанель','Руслан','Аделя'];const students=names.map((name,i)=>{const student_id='DEMO-'+String(i+1).padStart(2,'0');return{...scopeData,student_id,name,key:S.personKey(state.profile,group,student_id),demo:true,demoTag:prefix};});state.school.roster.push(...students);const subjects=[...new Set([state.profile.subject,'Английский язык','Информатика'])];while(subjects.length<3)subjects.push('Математика');students.forEach((p,i)=>subjects.forEach((subject,j)=>{for(let n=0;n<2;n++)state.school.grades.push({...scopeData,id:uid(),studentKey:p.key,subject,title:n?'Практическая работа':'Самостоятельная работа',score:55+(i*11+j*7+n*13)%46,max:100,date:today(),comment:'Синтетический пример',demo:true});}));
[1,2,4].forEach((day,i)=>state.school.lessons.push({...scopeData,id:uid(),day,start:['09:00','10:00','11:00'][i],end:['09:45','10:45','11:45'][i],subject:subjects[i],room:'Кабинет '+(201+i),demo:true}));
subjects.slice(0,2).forEach((subject,i)=>state.school.homework.push({...scopeData,id:uid(),subject,title:i?'Подготовить короткий ответ':'Закрепляем изученную тему',description:'Демонстрационное задание: повторите материал урока и выполните упражнения 1–3.',due:today(),demo:true}));state.school.remarks.push({...scopeData,id:uid(),studentKey:students[0].key,subject:subjects[0],kind:'praise',text:'Отличная работа на занятии! Продолжайте в том же темпе.',date:today(),demo:true});state.school.group=group;state.class=group;persist();navigate('teacherhome');render();toast('Добавлен демонстрационный кабинет на 20 человек');}
function activeTutorial(){return isTeacher()?[{page:'teacherhome',title:'Ваш кабинет учителя',text:'Здесь собраны быстрые действия, учебная группа и планы. Добавьте свою группу или откройте пример на 20 человек.',target:'#content',icon:'⌂'},{page:'journal',title:'Журнал оценок',text:'Выберите предмет и группу сверху. Добавляйте оценки за конкретную работу, указывайте максимум баллов. Записи можно изменить или удалить.',target:'#content',icon:'▤'},{page:'schedule',title:'Расписание недели',text:'Добавляйте занятия с днём, временем и аудиторией. Пересекающиеся занятия не сохраняются.',target:'#content',icon:'◷'},{page:'homework',title:'Практика и обратная связь',text:'Задавайте домашние задания со сроком. В разделе «Обратная связь» можно оставить индивидуальное замечание или похвалу.',target:'#content',icon:'✓'},{page:'ranking',title:'Рейтинг по предметам',text:'Места рассчитываются внутри выбранной группы. Можно выбрать конкретный предмет или общий результат. Без оценок место не присваивается.',target:'#content',icon:'↗'},{page:'hours',title:'План и личные настройки',text:'Распределите часы по темам и сохраните общий объём. В настройках доступны тема, акцент, аватар и анимации. Диагностические тесты по-прежнему загружаются в разделе «Данные».',target:'#content',icon:'✦'}]:[{page:'studenthome',title:'Ваш учебный кабинет',text:'Выберите себя в списке группы. Здесь появятся ваши оценки и невыполненные задания.',target:'#content',icon:'⌂'},{page:'journal',title:'Мои результаты',text:'В журнале видны только ваши оценки. Переключайте предмет сверху. Добавлять и изменять оценки может учитель.',target:'#content',icon:'▤'},{page:'schedule',title:'Расписание',text:'Все занятия вашей группы собраны по дням недели. Время и аудиторию задаёт учитель.',target:'#content',icon:'◷'},{page:'homework',title:'Домашние задания',text:'Следите за сроками и отмечайте выполненные задания. Отметку можно отменить.',target:'#content',icon:'✓'},{page:'ranking',title:'Учимся вместе',text:'Рейтинг показывает результаты группы по отдельным предметам. Вашу строку мы выделяем. Остальные участники отображаются по ID.',target:'#content',icon:'↗'},{page:'settings',title:'Ваше пространство',text:'Выберите светлую, тёмную или тёплую тему, цвет акцента и аватар. Туториал можно повторить в любой момент.',target:'#content',icon:'⚙'}];}
function openRole(canClose=false){if($('#settings-dialog').open)$('#settings-dialog').close();if($('#tutorial'))$('#tutorial').hidden=true;const d=$('#role-dialog');d.innerHTML='<div class="modal-head"><span class="eyebrow">ДОБРО ПОЖАЛОВАТЬ В EDULENS</span>'+(canClose?'<button class="icon-button" id="close-role" aria-label="Закрыть выбор роли">×</button>':'')+'</div><div class="role-welcome"><span class="role-spark">✦</span><h2>Как вы будете учиться<br>и менять обучение?</h2><p>Выберите пространство, которое подходит вам.</p></div><div class="role-options"><button class="role-card" data-role="student"><span class="role-art student-art">✧</span><b>Я ученик / студент</b><p>Мои оценки, задания,<br>расписание и прогресс</p><span>Открыть мой кабинет →</span></button><button class="role-card" data-role="teacher"><span class="role-art teacher-art">✦</span><b>Я учитель</b><p>Группа, журнал, расписание<br>и учебный план</p><span>Открыть кабинет учителя →</span></button></div><p class="role-local-note">Локальный режим: выбор кабинета для работы с данными этого браузера.</p>';if(canClose)$('#close-role').onclick=()=>d.close();d.oncancel=e=>{if(!canClose)e.preventDefault();};d.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{state.school.role=b.dataset.role;state.class='all';state.book='all';hoursDraft=null;persist();history.replaceState(null,'','#'+roleHome());d.close();render();if(!state.configured)openSettings(true);else afterInstitution();});d.showModal();}
function afterInstitution(){if(isStudent()&&!currentStudent())openIdentity();else if(!state.tutorialDone)startTutorial();}
function openIdentity(){const d=$('#identity-dialog'),ps=allPeople();d.innerHTML='<div class="modal-head"><span class="eyebrow">МОЁ МЕСТО В ГРУППЕ</span><button class="icon-button" id="identity-close" aria-label="Закрыть выбор обучающегося">×</button></div><h2>Кто вы в списке группы?</h2><p>Выбор связывает ваш кабинет с оценками и заданиями в этом браузере.</p>'+(ps.length?'<form id="identity-form" class="record-form">'+selectField('Обучающийся','studentKey',[['','Выберите себя'],...ps.map(p=>[p.key,p.name+' · '+p.group])],state.school.studentKey)+'<div class="form-feedback full-field" id="identity-error" role="alert"></div><button class="button primary" type="submit">Открыть мой кабинет</button></form>':'<div class="callout">Список пока пуст. Учитель может добавить обучающихся в разделе «Класс / группа».</div><button class="button primary" id="identity-empty">Открыть кабинет</button>');$('#identity-close').onclick=()=>d.close();if(ps.length)$('#identity-form').onsubmit=e=>{e.preventDefault();const selected=allPeople().find(p=>p.key===new FormData(e.target).get('studentKey'));if(!selected){$('#identity-error').textContent='Выберите себя из списка';return;}state.school.studentKey=selected.key;state.school.group=selected.group;state.class=selected.group;persist();d.close();render();if(!state.tutorialDone)startTutorial();};else $('#identity-empty').onclick=()=>{d.close();render();};d.showModal();}
function bindSchool(){document.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>openRecord(b.dataset.new));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openRecord(b.dataset.edit,b.dataset.id));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>removeRecord(b.dataset.delete,b.dataset.id));document.querySelectorAll('[data-rank-subject]').forEach(b=>b.onclick=()=>{rankingSubject=b.dataset.rankSubject;render();});document.querySelectorAll('[data-done]').forEach(b=>b.onclick=()=>{const p=currentStudent(),id=b.dataset.done;if(!isStudent()||!p||!scoped('homework').some(h=>h.id===id))return;const was=isDone(id);state.school.done=state.school.done.filter(d=>!(d.homeworkId===id&&d.studentKey===p.key));if(!was)state.school.done.push({homeworkId:id,studentKey:p.key});persist();render();toast(was?'Отметка отменена':'Отлично! Задание отмечено выполненным');});if($('#load-school-demo'))$('#load-school-demo').onclick=seedSchoolDemo;if($('#choose-identity'))$('#choose-identity').onclick=openIdentity;
if(page==='hours'&&isTeacher()){
 document.querySelectorAll('[data-hour-row] input,#teacher-budget').forEach(el=>el.oninput=readHours);
 $('#add-hour-topic').onclick=()=>{const draft=readHours();if(draft.rows.length>=100){toast('Не более 100 тем');return;}draft.rows.push({name:'',hours:1,locked:false});render();};
 document.querySelectorAll('[data-remove-hour]').forEach(b=>b.onclick=()=>{readHours().rows.splice(Number(b.dataset.removeHour),1);render();});
 $('#save-teacher-hours').onclick=()=>{if(!guardTeacher())return;const d=readHours(),errors=S.hourErrors(d.rows,d.budget);if(errors.length){$('#hours-feedback').innerHTML='<div class="error-list">'+esc(errors.join('\n'))+'</div>';return;}state.school.hourPlans=state.school.hourPlans.filter(p=>p.key!==d.key);state.school.hourPlans.push({...JSON.parse(JSON.stringify(d)),updatedAt:new Date().toLocaleString('ru-RU',{timeZone:'Asia/Qyzylorda'})});persist();render();toast('Учебный план сохранён');};
 $('#download-teacher-hours').onclick=()=>{const d=readHours();download('edulens-teacher-hours.csv',E.csv(d.rows.map(r=>({group:activeGroup(),subject:state.profile.subject,topic:r.name,hours:r.hours,locked:r.locked,budget:d.budget})),['group','subject','topic','hours','locked','budget']));};
 $('#suggest-teacher-hours').onclick=()=>{if(!guardTeacher())return;const d=readHours(),errors=S.hourErrors(d.rows,d.budget);if(errors.length){$('#hours-feedback').innerHTML='<div class="error-list">'+esc(errors.join('\n'))+'</div>';return;}const ts=E.aggregate(contextRows().filter(r=>r.class===activeGroup()),state.target),unlocked=d.rows.filter(r=>!r.locked),candidates=unlocked.map(r=>{const t=ts.find(t=>t.name===r.name);return t?{...t,hours:r.hours}:{name:r.name,hours:r.hours,n:0,questions:0,post:null,below:null};});const proposal=E.makePlan(candidates,{target:state.target,min:1,cap:state.cap});let changed=false;d.rows=d.rows.map(r=>{const p=proposal.find(t=>t.name===r.name);if(r.locked||!p)return r;if(r.hours!==p.proposed)changed=true;return{...r,hours:p.proposed};});render();$('#hours-feedback').innerHTML='<div class="'+(changed?'success-box':'callout warning')+'">'+(changed?'Предложение рассчитано. Общий объём сохранён. Проверьте его и нажмите «Сохранить план».':'При текущих данных допустимого переноса нет. Нужны сопоставимые диагностические результаты минимум 10 обучающихся и 2 заданий по теме. Можно распределить часы вручную.')+'</div>';};
}
if(page==='settings'){
 const name=$('#display-name');if(name)name.onchange=()=>{state.school.teacherName=name.value.trim()||'Учитель';persist();render();};
 document.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{state.school.preferences.theme=b.dataset.themeChoice;persist();render();});
 document.querySelectorAll('[data-accent-choice]').forEach(b=>b.onclick=()=>{state.school.preferences.accent=b.dataset.accentChoice;persist();render();});
 document.querySelectorAll('[data-avatar]').forEach(b=>b.onclick=()=>{state.school.preferences.avatar=b.dataset.avatar;state.school.preferences.photo='';persist();render();});
 $('#motion-toggle').onchange=e=>{state.school.preferences.motion=e.target.checked;persist();applyPreferences();};
 $('#avatar-file').onchange=e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>500*1024){toast('Выберите PNG, JPG или WebP до 500 КБ');return;}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onerror=()=>toast('Не удалось прочитать изображение');img.onload=()=>{state.school.preferences.photo=reader.result;persist();render();toast('Фото профиля обновлено');};img.src=reader.result;};reader.readAsDataURL(file);};
 if($('#remove-avatar'))$('#remove-avatar').onclick=()=>{state.school.preferences.photo='';persist();render();};
 $('#settings-institution').onclick=()=>openSettings();$('#settings-switch-role').onclick=()=>openRole(true);$('#settings-tutorial').onclick=startTutorial;
}}
for(const id of ['role-dialog','record-dialog','identity-dialog']){const d=document.createElement('dialog');d.id=id;document.body.append(d);}
for(const p of state.school.roster)if(p.demo&&p.demoTag)p.name=p.name.replace(/ · DEMO-\d+$/,'');
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.school.preferences.theme==='system')applyPreferences();});
applyPreferences();render();if(!state.school.role)openRole();else if(!state.configured)openSettings(true);else if(isStudent()&&!currentStudent())openIdentity();
